import re
import os
from collections import defaultdict

# Find all exported functions/methods in internal/
functions = {}
for root, dirs, files in os.walk('internal'):
    for file in files:
        if file.endswith('.go') and not file.endswith('_test.go'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', errors='ignore') as f:
                content = f.read()
                # Match exported function declarations: func Name or func (receiver) Name
                for match in re.finditer(r'func\s+(?:\([^)]+\))?\s+([A-Z][A-Za-z0-9_]*)\s*\(', content):
                    func_name = match.group(1)
                    functions[func_name] = filepath

# Now count calls to each function
call_counts = defaultdict(int)
for root, dirs, files in os.walk('.'):
    for file in files:
        if file.endswith('.go') and not file.endswith('_test.go'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', errors='ignore') as f:
                content = f.read()
                for func_name in functions.keys():
                    # Count calls to the function (word boundary match)
                    count = len(re.findall(r'\b' + re.escape(func_name) + r'\s*\(', content))
                    if count > 0:
                        call_counts[func_name] += count

# Sort by call count
sorted_funcs = sorted(call_counts.items(), key=lambda x: x[1], reverse=True)

for func_name, count in sorted_funcs[:30]:
    if count > 3:
        print(f"{count:3d} — {func_name:30s} — {functions[func_name]}")
